/**
 * Self-contained ring tones for the Telnyx WebRTC dial pad — generated
 * as short looping WAV data URIs (via a one-off Node script, not checked in)
 * so the dialer has audible feedback out of the box with no separate asset
 * files to host or a CDN dependency. The SDK loops these automatically
 * (`new TelnyxRTC({ ringtoneFile, ringbackFile })`) whenever a call enters
 * the ringing state, so each one only needs to cover a single ring cycle.
 */

/** Ringback (what you hear while the number you're calling is ringing): classic 440+480Hz dual tone, 1s on / 2s off. */
export const RINGBACK_TONE_URL = "data:audio/wav;base64,";

/** Ringtone (what plays when someone is calling you): two short bell-like bursts, then a pause. */
export const RINGTONE_URL = "data:audio/wav;base64,";
